#!/usr/bin/env bash
# Generates the validation media library used by CI (all content synthetic, generated by FFmpeg).
# Layout follows Jellyfin naming so the server identifies movies, a series, seasons and episodes.
set -euo pipefail
OUT=${1:-media}
FONT=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf
mkdir -p "$OUT/movies" "$OUT/tv/Skylark Isles/Season 01"
TMP=$(mktemp -d)

pattern() { # duration size rate [extra lavfi]
  echo "testsrc2=duration=$1:size=$2:rate=$3"
}

# ---------- subtitle sources ----------
cat > "$TMP/plain.srt" <<'SRT'
1
00:00:00,500 --> 00:00:03,000
Plain SubRip line one

2
00:00:03,200 --> 00:00:06,000
<i>Italic</i> SubRip line two
SRT

cat > "$TMP/forced.srt" <<'SRT'
1
00:00:01,000 --> 00:00:04,000
[FORCED] Sign: "Station"
SRT

cat > "$TMP/spa.srt" <<'SRT'
1
00:00:00,500 --> 00:00:05,000
Subtítulo en español
SRT

cat > "$TMP/styled.ass" <<'ASS'
[Script Info]
ScriptType: v4.00+
PlayResX: 1920
PlayResY: 1080
WrapStyle: 0

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,DejaVu Sans,64,&H00FFFFFF,&H000000FF,&H00101010,&H90000000,-1,0,0,0,100,100,0,0,1,3.5,2,2,80,80,60,1
Style: Top,DejaVu Sans,52,&H0000E5FF,&H000000FF,&H00000000,&H80000000,-1,-1,0,0,100,100,0,0,1,3,0,8,80,80,50,1
Style: Karaoke,DejaVu Sans,70,&H00FFFFFF,&H00FF8800,&H00000000,&H80000000,-1,0,0,0,100,100,2,0,1,4,0,2,80,80,140,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,0:00:00.30,0:00:05.50,Default,,0,0,0,,Bottom dialogue with {\c&H66CCFF&}colour{\r} and {\i1}italics{\i0}
Dialogue: 0,0:00:00.30,0:00:05.50,Top,,0,0,0,,Simultaneous top line (alignment 8)
Dialogue: 1,0:00:01.00,0:00:05.50,Karaoke,,0,0,0,,{\k40}Ka{\k40}ra{\k40}o{\k60}ke {\k50}ef{\k50}fect
Dialogue: 2,0:00:00.50,0:00:05.50,Default,,0,0,0,,{\an7\pos(120,120)\fs40\bord2\1c&H00FF00&}\N{\an7}Positioned sign (\pos)
Dialogue: 0,0:00:06.00,0:00:11.00,Default,,0,0,0,,{\fad(400,400)}Fade in / fade out
ASS

cat > "$TMP/anime.ass" <<'ASS'
[Script Info]
ScriptType: v4.00+
PlayResX: 1920
PlayResY: 1080
ScaledBorderAndShadow: yes

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Dialogue,DejaVu Sans,62,&H00FFFFFF,&H000000FF,&H00202020,&HA0000000,-1,0,0,0,100,100,0,0,1,3.2,1.5,2,90,90,55,1
Style: Sign,DejaVu Sans,58,&H00203040,&H000000FF,&H00F0F0F0,&H00000000,-1,0,0,0,100,100,1,0,1,2,0,5,0,0,0,1
Style: OP-Romaji,DejaVu Sans,48,&H00FFFFFF,&H00C080FF,&H00602080,&H00000000,-1,0,0,0,100,100,1,0,1,2.5,0,8,40,40,40,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Comment: 0,0:00:00.00,0:00:00.00,Sign,,0,0,0,,--- typesetting ---
Dialogue: 5,0:00:00.20,0:00:09.80,Sign,,0,0,0,,{\an5\pos(1440,300)\frz-12\fscx110\blur0.6\bord3\3c&HFFFFFF&}Rotated Shop Sign
Dialogue: 4,0:00:00.20,0:00:09.80,Sign,,0,0,0,,{\an5\move(300,800,900,700,0,9000)\frz8\1c&H3030E0&}Moving sign (\move)
Dialogue: 6,0:00:02.00,0:00:09.80,Sign,,0,0,0,,{\an5\pos(960,540)\clip(760,480,1160,600)\t(0,3000,\frz360)\fs90\1c&H10D0FF&}CLIP+T
Dialogue: 3,0:00:00.20,0:00:09.80,OP-Romaji,,0,0,0,,{\k30}Ki{\k30}ra{\k30}me{\k50}ku {\k40}so{\k40}ra
Dialogue: 0,0:00:00.20,0:00:04.80,Dialogue,,0,0,0,,{\i1}Overlapping{\i0} line one
Dialogue: 0,0:00:01.50,0:00:06.00,Dialogue,,0,0,0,,Overlapping line two (stacks above)
Dialogue: 0,0:00:06.20,0:00:09.80,Dialogue,,0,0,0,,{\fad(300,300)\be1}Edge-blur fade
ASS

# Repeat every subtitle event every 10 s so styled subtitles are on screen for the whole clip.
repeat_events() { # file
  python3 - "$1" <<'PY'
import re, sys
p = sys.argv[1]; lines = open(p).read().split("\n")
head = [l for l in lines if not l.startswith("Dialogue:")]
ev = [l for l in lines if l.startswith("Dialogue:")]
def shift(t, s):
    h, m, rest = t.split(":"); sec = float(rest) + int(m) * 60 + int(h) * 3600 + s
    return "%d:%02d:%05.2f" % (sec // 3600, (sec % 3600) // 60, sec % 60)
out = []
for k in range(0, 4):
    for l in ev:
        f = l.split(",", 9)
        f[1] = (f[1].split(": ")[0] + ": " + shift(f[1].split(": ")[1], 10 * k)) if ": " in f[1] else shift(f[1], 10 * k)
        f[2] = shift(f[2], 10 * k)
        out.append(",".join(f))
open(p, "w").write("\n".join(head + out) + "\n")
PY
}
repeat_events "$TMP/styled.ass"
repeat_events "$TMP/anime.ass"

# ---------- 1) H.264 + AAC + embedded SRT, plus external .en.srt sidecar ----------
D="$OUT/movies/Harbor Lights (2021)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 30 1920x1080 24)" -f lavfi -i "sine=frequency=440:duration=30" -i "$TMP/plain.srt" \
  -map 0 -map 1 -map 2 -c:v libx264 -preset veryfast -crf 26 -pix_fmt yuv420p -c:a aac -b:a 128k -c:s srt \
  -metadata:s:a:0 language=eng -metadata:s:s:0 language=eng -metadata title="Harbor Lights" "$D/Harbor Lights (2021).mkv"
cp "$TMP/plain.srt" "$D/Harbor Lights (2021).en.srt"

# ---------- 2) HEVC Main10 + AC3 5.1 + embedded styled ASS + font attachment ----------
D="$OUT/movies/Glass Meridian (2023)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 30 1920x1080 24)" -f lavfi -i "sine=frequency=330:duration=30" -i "$TMP/styled.ass" \
  -map 0 -map 1 -map 2 -c:v libx265 -preset ultrafast -x265-params log-level=error -pix_fmt yuv420p10le -profile:v main10 \
  -c:a ac3 -ac 6 -b:a 384k -c:s ass -attach "$FONT" -metadata:s:t:0 mimetype=application/x-truetype-font -metadata:s:t:0 filename=DejaVuSans-Bold.ttf \
  -metadata:s:a:0 language=eng -metadata:s:s:0 language=eng -metadata:s:s:0 title="English (styled ASS)" "$D/Glass Meridian (2023).mkv"

# ---------- 3) MKV with multiple audio and subtitle tracks ----------
D="$OUT/movies/Seven Rivers (2019)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 30 1280x720 25)" \
  -f lavfi -i "sine=frequency=500:duration=30" -f lavfi -i "sine=frequency=600:duration=30" -f lavfi -i "sine=frequency=700:duration=30" \
  -i "$TMP/styled.ass" -i "$TMP/forced.srt" -i "$TMP/spa.srt" \
  -map 0 -map 1 -map 2 -map 3 -map 4 -map 5 -map 6 \
  -c:v libx264 -preset veryfast -crf 28 -c:a:0 aac -ac:a:0 2 -c:a:1 ac3 -ac:a:1 6 -c:a:2 eac3 -ac:a:2 6 \
  -c:s:0 ass -c:s:1 srt -c:s:2 srt \
  -metadata:s:a:0 language=eng -metadata:s:a:0 title="English Stereo" \
  -metadata:s:a:1 language=jpn -metadata:s:a:1 title="Japanese 5.1" \
  -metadata:s:a:2 language=spa -metadata:s:a:2 title="Spanish 5.1 (E-AC3)" \
  -metadata:s:s:0 language=eng -metadata:s:s:0 title="English Full" \
  -metadata:s:s:1 language=eng -metadata:s:s:1 title="English Forced" -disposition:s:1 forced \
  -metadata:s:s:2 language=spa -metadata:s:s:2 title="Spanish" \
  "$D/Seven Rivers (2019).mkv"

# ---------- 4) 4K HDR10 HEVC Main10 (short) ----------
D="$OUT/movies/Ember Field (2024)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 6 3840x2160 24)" -f lavfi -i "sine=frequency=250:duration=6" \
  -c:v libx265 -preset ultrafast -pix_fmt yuv420p10le -profile:v main10 \
  -x265-params "log-level=error:hdr10=1:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc:master-display=G(13250,34500)B(7500,3000)R(34000,16000)WP(15635,16450)L(10000000,1):max-cll=1000,400" \
  -color_primaries bt2020 -color_trc smpte2084 -colorspace bt2020nc -c:a eac3 -ac 6 \
  "$D/Ember Field (2024).mkv"

# ---------- 5) Needs server transcoding: MPEG-4 Part 2 + MP3 in AVI ----------
D="$OUT/movies/Old Reel (1999)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 20 720x480 25)" -f lavfi -i "sine=frequency=800:duration=20" \
  -c:v mpeg4 -vtag XVID -q:v 5 -c:a libmp3lame -b:a 128k "$D/Old Reel (1999).avi"

# ---------- 6) Series: anime-style typesetting, HEVC Main10, 3 episodes ----------
for e in 1 2 3; do
  ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 20 1920x1080 24)" -f lavfi -i "sine=frequency=$((300 + e * 50)):duration=20" -i "$TMP/anime.ass" \
    -map 0 -map 1 -map 2 -c:v libx265 -preset ultrafast -x265-params log-level=error -pix_fmt yuv420p10le -profile:v main10 \
    -c:a aac -c:s ass -attach "$FONT" -metadata:s:t:0 mimetype=application/x-truetype-font -metadata:s:t:0 filename=DejaVuSans-Bold.ttf \
    -metadata:s:a:0 language=jpn -metadata:s:s:0 language=eng -metadata:s:s:0 title="Signs & Songs" \
    -metadata title="Episode $e" "$OUT/tv/Skylark Isles/Season 01/Skylark Isles - S01E0$e.mkv"
done

rm -rf "$TMP"
find "$OUT" -type f | sort
